256	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = DependencyEntry> + '_> {
257	        let mut entries = Vec::new();
258	
259	        for (section_name, kind) in [
260	            ("dependencies", DepKind::Runtime),
261	            ("devDependencies", DepKind::Dev),
262	            ("peerDependencies", DepKind::Peer),
263	            ("optionalDependencies", DepKind::Optional),
264	        ] {
265	            if let Some(obj) = self.doc.get(section_name).and_then(|v| v.as_object()) {
266	                for (name, val) in obj {
267	                    if let Some(v_str) = val.as_str() {
268	                        let spec = parse_npm_spec_str(v_str, self.npm_workspace_kind);
269	                        entries.push(DependencyEntry {
270	                            name: name.clone(),
271	                            kind,
272	                            spec,
273	                            inherited: false,
274	                        });
275	                    }
276	                }
277	            }
278	        }
279	
280	        Box::new(entries.into_iter())
281	    }
