343	    fn update_optional_dependencies(
344	        &mut self,
345	        updates: &[(String, Version)],
346	        permit: &ApplyPermit,
347	    ) -> Result<(), ManifestError> {
348	        let section = self
349	            .doc
350	            .entry("optionalDependencies".to_string())
351	            .or_insert_with(|| Value::Object(Map::new()))
352	            .as_object_mut()
353	            .ok_or_else(|| ManifestError::FormattingNotPreserved {
354	                path: self.path.clone(),
355	                message: "optionalDependencies is not an object".to_string(),
356	            })?;
357	
358	        for (name, ver) in updates {
359	            section.insert(name.clone(), Value::String(ver.render().to_string()));
360	        }
361	
362	        self.persist(permit)
363	    }
