415	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
416	    match spec {
417	        DepSpec::CargoBare(_) => Some(DepSpec::CargoBare(target.clone())),
418	        DepSpec::Range(_, original) => {
419	            if original.contains(',') {
420	                let parts: Vec<&str> = original.split(',').collect();
421	                let mut rewritten_parts = Vec::new();
422	                for part in parts {
423	                    let part_trimmed = part.trim();
424	                    let (prefix, rest) = crate::common::split_single_operator_prefix(part_trimmed)?;
425	                    if prefix.starts_with('>')
426	                        || prefix.starts_with('=')
427	                        || prefix.starts_with('^')
428	                        || prefix.starts_with('~')
429	                    {
430	                        let rendered = format!("{prefix}{}", render_at_precision(target, rest));
431	                        rewritten_parts.push(rendered);
432	                    } else if prefix.starts_with('<') {
433	                        // Upper-bound clauses are never rewritten (the clause text
434	                        // is preserved verbatim), but we must still check whether
435	                        // the target actually falls within it. If it doesn't, the
436	                        // rewrite would silently produce an impossible constraint
437	                        // (e.g. ">=2.1.0, <2.0.0"), so decline with None. If it
438	                        // does, the upper bound clause is passed through unchanged.
439	                        let bound = Version::parse(rest, target.grammar()).ok()?;
440	                        let ordering = target.partial_compare(&bound)?;
441	                        let exceeds_bound = if prefix == "<=" {
442	                            ordering == std::cmp::Ordering::Greater
443	                        } else {
444	                            ordering != std::cmp::Ordering::Less
445	                        };
446	                        if exceeds_bound {
447	                            return None;
448	                        }
449	                        rewritten_parts.push(part_trimmed.to_string());
450	                    } else {
451	                        rewritten_parts.push(part_trimmed.to_string());
452	                    }
453	                }
454	                let rendered = rewritten_parts.join(", ");
455	                let req = VersionReq::parse(&rendered, Ecosystem::Cargo).ok()?;
456	                return Some(DepSpec::Range(req, rendered));
457	            }
458	            let (prefix, rest) = crate::common::split_single_operator_prefix(original)?;
459	            if rest.contains('*') {
460	                return None;
461	            }
462	            let rendered = format!("{prefix}{}", render_at_precision(target, rest));
463	            let req = VersionReq::parse(&rendered, Ecosystem::Cargo).ok()?;
464	            Some(DepSpec::Range(req, rendered))
465	        }
466	        _ => None,
467	    }
468	}
